<script>
 import {usePresentation} from "$lib/presentation.svelte.js";
 import SimulationNotice from "./SimulationNotice.svelte";
 import HistoryChart from './HistoryChart.svelte';import {formatValue} from '$lib/energy';
 let {data:incoming,range='today',preview=false}=$props();
 const presentation=usePresentation(()=>incoming,()=>range);let data=$derived(presentation.data);

 let totals=$derived(data.history?.totals || {});
 function download(){const rows=['timestamp_cat,solar_kwh,consumption_kwh,data_source'];const times=[...new Set([...(data.history?.solar||[]).map(p=>p.time),...(data.history?.consumption||[]).map(p=>p.time)])].sort();for(const time of times){const cat=new Date(Date.parse(time)+7200000).toISOString().replace('Z','+02:00');rows.push([cat,data.history?.solar?.find(p=>p.time===time)?.value??'',data.history?.consumption?.find(p=>p.time===time)?.value??'',data.simulated?'simulated':preview?'illustrative':'provider'].join(','));}const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=`${data.simulated?'simulated-test':preview?'illustrative-sample':'gridubuntu'}-energy-${range}.csv`;a.click();URL.revokeObjectURL(url);}
</script>
{#if data.simulated}<SimulationNotice/>{/if}
<div class="page-heading"><div><div class="breadcrumb">MY RESIDENCE <span>/</span> ENERGY HISTORY</div><h1>Your energy, over time.</h1><p>{data.node?.display_name || 'Your residence'} <span>·</span> Generation and consumption in kWh</p></div><button class="refresh-button" onclick={download} disabled={!data.history?.solar?.length&&!data.history?.consumption?.length}>Download CSV ↓</button></div>
<div class="history-controls"><div class="period-tabs" aria-label="Energy history period">{#each [['today','Today'],['7d','7 days'],['30d','30 days']] as [value,label]}<a class:active={range===value} aria-current={range===value?'page':undefined} href={preview?'/portal-preview?view=history':`/portal/history?range=${value}`}>{label}</a>{/each}</div><span>{preview?'Sample day · illustrative data':'Harare time · CAT (UTC+2)'}</span></div>
{#if preview}<div class="notice neutral"><p>The preview illustrates a single day. Live date ranges become available after connection.</p></div>{/if}
<section class="history-totals">{#each [['Solar generated',totals.solar],['Energy consumed',totals.consumption],['Grid import',totals.gridImport],['Grid export',totals.gridExport]] as [label,value]}<article class="metric-card"><span class="metric-label">{label}</span><div class="metric-value">{formatValue(value,'',2)} <small>kWh</small></div><span class="metric-caption">{range==='today'?'Today':range==='7d'?'Last 7 calendar days':'Last 30 calendar days'}</span></article>{/each}</section>
<section class="panel"><div class="panel-heading"><div><span class="overline">{data.simulated?'ENERGY HISTORY':'MEASURED ENERGY'}</span><h2>Generation alongside consumption</h2></div></div><HistoryChart history={data.history} {range}/></section>
<section class="panel history-explanation"><h2>Reading your history</h2><div><p><strong>Power and energy are different.</strong> The overview shows power in kW at a point in time. This history shows energy in kWh during each period.</p><p><strong>Missing readings stay missing.</strong> A gap does not mean zero consumption. Provider totals can differ from visible bars when part of a period is unavailable.</p><p><strong>Forecasting comes later.</strong> {data.simulated?'Demand planning follows the collection of historical usage.':'This release presents measured history.'} Predictions will be introduced after sufficient data and accuracy testing.</p></div></section>
